package moe.kiwi.thinkos.plugin

import org.json.JSONObject

/** Runtime presentation handles. Wire DTOs and validation are generated by shared/gen. */
data class PluginPage(
    val pluginId: String, val id: String, val title: String, val view: JSONObject,
    val variants: List<String> = emptyList(), val roles: List<String> = emptyList(),
    val priority: Int = 0, val live: Boolean = false,
    /** The `@key` of a translated title, kept so a page that shows its title can follow a language change. */
    val titleKey: String? = null,
) { val key: String get() = "$pluginId.$id" }

data class PluginWidget(val pluginId: String, val id: String, val view: JSONObject, val opens: String? = null,
    val alternates: Map<String, JSONObject> = emptyMap()) {
    val key: String get() = "$pluginId.$id"
}

/** The tile animations a plugin may request by name (ADR-028). The OS owns how each one looks. */
object TileAnimations {
    val names = setOf("pulse", "flip", "nudge")
    /** Per plugin and animation; a plugin cannot use this as a strobe. */
    const val COOLDOWN_MILLIS = 1_000L
}

data class PluginDiagnostic(val id: String, val version: String, val bytes: Long, val disabled: Boolean, val error: String?,
    val unresolved: List<String> = emptyList())

internal class NativeLua(private val bridge: (String, Array<Any?>, Int) -> Any?) {
    data class Step(val taskId: Int, val status: Int, val message: String?, val cpuMicros: Long, val wallMicros: Long) {
        val failed get() = status >= 2
        val resourceFailure get() = status in 3..5
    }
    companion object {
        const val DONE = 0
        const val WAITING = 1
        init { System.loadLibrary("tos") }
    }
    private var handle = create()
    private external fun create(): Long
    private external fun start(handle: Long, entry: String?, args: Array<Any?>?, source: String?, label: String?): Step
    private external fun resume(handle: Long, id: Int, args: Array<Any?>): Step
    private external fun bind(handle: Long)
    private external fun cancel(handle: Long, id: Int)
    private external fun memory(handle: Long): Long
    private external fun destroy(handle: Long)
    @Suppress("unused")
    fun call(method: String, args: Array<Any?>, taskId: Int): Any? = bridge(method, args, taskId)
    fun run(code: String, name: String = "plugin") {
        check(handle != 0L) { "Lua allocation failed" }
        val step = start(handle, null, null, code, name)
        if (step.status == WAITING) { cancel(handle, step.taskId); error("Async API requires an event handler") }
        if (step.failed) throw LuaFailure(step)
    }
    fun bindEntries() = bind(handle)
    fun dispatch(name: String, args: Array<Any?> = emptyArray()): Step = start(handle, "dispatch", arrayOf(name, *args), null, null)
    fun timer(id: Int, repeating: Boolean): Step = start(handle, "timer", arrayOf(id.toLong(), repeating), null, null)
    fun resume(id: Int, args: Array<Any?>): Step = resume(handle, id, args)
    fun cancel(id: Int) { if (handle != 0L) cancel(handle, id) }
    fun bytes(): Long = if (handle == 0L) 0 else memory(handle)
    fun close() { if (handle != 0L) { destroy(handle); handle = 0 } }
}
internal class LuaFailure(val step: NativeLua.Step) : IllegalStateException(step.message)
